// Pseudocode for onMessage
class RuleEngine {
  constructor(windowMs=60000) {
    this.windowMs = windowMs;
    this.state = new Map(); // sensorId -> [{ts,value}, ...], plus sum/count
  }
  onMessage(event){
    const {sensorId, ts, value} = event;
    const bucket = this.state.get(sensorId) || {q:[], sum:0, count:0};
    // prune old
    while (bucket.q.length && bucket.q[0].ts <= ts - this.windowMs) {
      const old = bucket.q.shift(); bucket.sum -= old.value; bucket.count--;
    }
    bucket.q.push({ts,value}); bucket.sum += value; bucket.count++;
    const avg = bucket.count ? bucket.sum / bucket.count : value;
    if (value > 1.2 * avg) { this.emitAlert(sensorId, ts, value, avg); }
    this.state.set(sensorId, bucket);
  }
  rollingAvgFor(sensorId){ const bucket = this.state.get(sensorId); return bucket?.count ? bucket.sum / bucket.count : null; }
  emitAlert(sensorId, ts, value, avg){ // write to threshold_alerts sink
